-- ============================================================================
-- V25 : Resync IDENTITY sequences after explicit-ID seed inserts
-- ============================================================================
-- Root cause:
--   V16 inserts seed rows into every table using explicit id values
--   (e.g. INSERT INTO order_item (id, ...) VALUES (1, ...)).
--   For GENERATED BY DEFAULT AS IDENTITY columns, an explicit-id insert does
--   NOT advance the internal sequence.  When Hibernate later inserts a row
--   without specifying an id, Postgres draws the next value from the stale
--   sequence (still 1) and collides with the seeded row → duplicate key error.
--
--   V5 only repairs tables that have NO identity generation (identity_kind IS
--   NULL) and no existing DEFAULT, so it silently skipped every table created
--   with GENERATED BY DEFAULT AS IDENTITY.
--
-- Fix:
--   For every table that carries an IDENTITY primary key, advance the sequence
--   to MAX(id) + 1 so the next auto-generated value is always safe.
--   The loop is fully idempotent – running it again is always harmless.
-- ============================================================================

DO $$
DECLARE
    tbl       TEXT;
    max_id    BIGINT;
    next_val  BIGINT;
    identity_col TEXT;
BEGIN
    FOR tbl IN
        SELECT DISTINCT table_name
        FROM information_schema.columns
        WHERE table_schema    = current_schema()
          AND column_name     = 'id'
          AND identity_generation IS NOT NULL   -- only IDENTITY columns
    LOOP
        -- Dynamically fetch the current MAX(id); treat empty tables as 0
        EXECUTE format('SELECT COALESCE(MAX(id), 0) FROM %I', tbl) INTO max_id;
        next_val := max_id + 1;

        -- RESTART WITH sets the next value the sequence will produce
        EXECUTE format(
            'ALTER TABLE %I ALTER COLUMN id RESTART WITH %s',
            tbl, next_val
        );

        RAISE NOTICE 'Resynced %.id sequence → next value = %', tbl, next_val;
    END LOOP;
END;
$$;

